fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since the array is guaranteed non-empty, we only need to check
    // that each element is <= the next one.
    for i in 1..arr.len() {
        if arr[i - 1] > arr[i] {
            return false;
        }
    }
    true
}

